-- El rol Administrador de las empresas existentes recibe todos los permisos que todavía no tenga
-- (los de sueldos, bienes de uso, presupuesto y demás entregas no se agregaron cuando se crearon).
-- Es la lista de TODOS_LOS_PERMISOS a la fecha, que es lo que recibe una empresa nueva.
UPDATE "Rol" r SET "permisos" = (
  SELECT array_agg(DISTINCT p ORDER BY p) FROM unnest(r."permisos" || ARRAY['empresa.administrar','usuario.administrar','rol.administrar','tercero.ver','tercero.editar','articulo.ver','articulo.editar','plancuentas.ver','plancuentas.editar','moneda.editar','tesoreria.maestros.editar','organizacion.editar','auditoria.ver','compras.config','oc.ver','oc.crear','oc.anular','ir.ver','ir.anular','fc.ver','fc.anular','oc.aprobar','ir.crear','fc.crear','op.ver','op.crear','op.anular','op.aprobar','pago.ejecutar','retenciones.config','tesoreria.ver','tesoreria.operar','tesoreria.aceptar','tesoreria.anular','tesoreria.tarjetas','asiento.registrar','contabilidad.cerrar','conciliacion.operar','venta.emitir','cobro.registrar','venta.ver','arca.configurar','impuestos.ver','impuestos.presentar','stock.ver','stock.operar','precios.editar','pedido.gestionar','bienes.ver','bienes.gestionar','presupuesto.ver','presupuesto.editar','sueldos.ver','sueldos.liquidar','informes.ver','venta.maestros','comisiones.liquidar','cobranzas.gestionar','intereses.liquidar','correo.configurar']::text[]) AS p
) WHERE r."nombre" = 'Administrador';
